draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // dog
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  // tail
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 70);
  ctx.stroke();

  // owner
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50 * Math.sin(t), H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 50 * Math.sin(t), H/2 + 20);
  ctx.lineTo(W/2 + 100 + 50 * Math.sin(t), H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 50 * Math.sin(t), H/2 + 30);
  ctx.lineTo(W/2 + 80 + 50 * Math.sin(t), H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100 + 50 * Math.sin(t), H/2 + 30);
  ctx.lineTo(W/2 + 120 + 50 * Math.sin(t), H/2 + 40);
  ctx.stroke();

  ctx.restore();
}
